WITH flattened AS (SELECT id, host, log_ts, level, status_code, k, v FROM app_logs LATERAL VIEW OUTER EXPLODE(context) x AS k, v), parsed AS (SELECT host, level, k, CAST((status_code & 8) != 0 AS INT) AS has_fault, SHIFTRIGHT(status_code, 2) AS status_code_high FROM flattened), with_windows AS (SELECT host, level, k, has_fault, status_code_high, COUNT(has_fault) OVER w_grp AS level_count_has_fault, CUME_DIST() OVER (PARTITION BY level, host ORDER BY has_fault DESC) AS has_fault_cume_dist FROM parsed WINDOW w_grp AS (PARTITION BY level)), with_windows_app_logs AS (SELECT host, level, k, has_fault, status_code_high, level_count_has_fault, has_fault_cume_dist, RANK() OVER (PARTITION BY host ORDER BY level_count_has_fault) AS level_count_has_fault_rank, CUME_DIST() OVER w_running AS status_code_high_cume_dist FROM with_windows WINDOW w_running AS (PARTITION BY level ORDER BY status_code_high NULLS FIRST)) SELECT level, COUNT_IF(host = 'h3') AS h3_events, SIZE(COLLECT_SET(k)) AS num_ks FROM with_windows_app_logs GROUP BY level ORDER BY num_ks DESC;
